# frozen_string_literal: true

# See `spec/frontend/path_helpers/*_spec.js` for specs
module Gitlab
  module JsRoutes
    PATH_HELPERS_PATH = 'app/assets/javascripts/lib/utils/path_helpers'
    EE_PATH_HELPERS_PATH = 'ee/app/assets/javascripts/lib/utils/path_helpers'
    PATH_HELPERS_DIRS = [PATH_HELPERS_PATH, EE_PATH_HELPERS_PATH].freeze

    class << self
      GENERATED_FILE_HEADER = <<~JS
        // This file is automatically generated from Rails routes.
        // DO NOT modify it manually.
        // To regenerate, run: bin/rake gitlab:js:routes
      JS

      # Match CI's invocation context: EE checkout, RAILS_ENV=test, and a
      # canonical Settings source. The route table is environment- and
      # config-dependent (e.g. routes inside `if Rails.env.development?` blocks,
      # and routes registered from omniauth providers in gitlab.yml), so the
      # output is only deterministic when we match what CI sees.
      #
      # In CI, scripts/static-analysis runs the task with RAILS_ENV=test and
      # scripts/prepare_build.sh has already canonicalized config/gitlab.yml,
      # so we trust the env and skip the local enforcement.
      def match_ci_env!(task_name)
        if %w[true 1].include?(ENV['FOSS_ONLY'].to_s)
          abort "#{task_name} cannot run with FOSS_ONLY=#{ENV['FOSS_ONLY']}; EE routes would be missing."
        end

        return if ENV['CI']
        return if Rails.env.test? && ENV['GITLAB_CONFIG'].to_s.end_with?('config/gitlab.yml.example')

        exec(
          { 'RAILS_ENV' => 'test', 'GITLAB_CONFIG' => Rails.root.join('config/gitlab.yml.example').to_s },
          'bin/rake', task_name
        )
      end

      def generate!
        original_route_source_locations = ActionDispatch::Routing::Mapper.route_source_locations

        begin
          unless original_route_source_locations
            # When route source locations are disabled (building in production and tests)
            # we temporarily enable them so we can use route.source_location to determine
            # how to split up the JavaScript path helpers into multiple files.
            ActionDispatch::Routing::Mapper.route_source_locations = true

            # Reload routes to capture source locations
            Rails.application.reload_routes!
          end

          # Clean the target dirs so routes removed since the last generation
          # don't leave stale helper files behind.
          PATH_HELPERS_DIRS.each do |path|
            FileUtils.rm_rf(Rails.root.join(path))
          end

          ee_route_pairs, ce_route_pairs = group_route_pairs_by_ee_or_ce(route_pairs)

          generate_path_helpers!(group_route_pairs_by_namespace(ee_route_pairs), EE_PATH_HELPERS_PATH)
          generate_path_helpers!(group_route_pairs_by_namespace(ce_route_pairs), PATH_HELPERS_PATH)

          # Exclude all routes so we can generate just the "core" utils from the
          # js-routes gem and put it in a separate file.
          # Then `import { __jsr } from '~/lib/utils/path_helpers/core'` is added to each
          # individual path helper file.
          js_routes_core = <<~JS
          #{GENERATED_FILE_HEADER}
          #{::JsRoutes.generate(exclude: [/.*/])}
          export { __jsr };
          JS
          core_file_path = Rails.root.join(PATH_HELPERS_PATH, 'core.js')

          write_file_if_changed(core_file_path, js_routes_core)

          utils = javascript_utils
          utils_file_path = Rails.root.join(PATH_HELPERS_PATH, 'utils.js')

          write_file_if_changed(utils_file_path, utils)
        ensure
          # Restore original setting
          ActionDispatch::Routing::Mapper.route_source_locations = original_route_source_locations
        end
      end

      private

      def route_source_location(route)
        return unless route.respond_to?(:source_location)
        return if route.source_location.nil?

        route.source_location
      end

      def write_file_if_changed(file_path, output)
        # Create the directory if it doesn't exist
        FileUtils.mkdir_p(File.dirname(file_path))

        # We don't need to rewrite file if it already exist and have same content.
        # It helps webpack understand that file wasn't changed.
        return if File.exist?(file_path) && File.read(file_path) == output

        File.write(file_path, output)
      end

      def route_pairs
        routes = Rails.application.routes.routes.to_a.select(&:name).index_by(&:name)
        organization_routes = ::Routing::OrganizationsHelper::MappedHelpers.find_route_pairs

        routes.filter_map do |route_name, route|
          # Skip if it is an organization scoped route (e.g. /o/:organization_path)
          next if organization_routes.value?(route_name)

          organization_route_name = organization_routes[route_name]

          # Return route pair of [global route, organization scoped route]
          next [route, routes[organization_route_name]] if organization_route_name

          # This route does not have an organization scoped counterpart
          [route, nil]
        end
      end

      # Group route pairs by their namespace (source location)
      def group_route_pairs_by_namespace(route_pairs)
        route_pairs.group_by do |global_route, _|
          source_location = route_source_location(global_route)
          if source_location.nil?
            'miscellaneous'
          else
            # Extract filename from source location (e.g., "config/routes/projects.rb:15" -> "projects")
            File.basename(source_location.split(':').first, '.rb')
          end
        end
      end

      # Group routes by EE or CE
      def group_route_pairs_by_ee_or_ce(route_pairs)
        route_pairs.partition do |global_route, _|
          source_location = route_source_location(global_route)
          next false if source_location.nil?

          source_location.delete_prefix(Rails.root.to_s).start_with?('/ee/config/routes')
        end
      end

      def generate_path_helpers!(grouped_route_pairs, base_path)
        grouped_route_pairs.each do |namespace, route_pairs|
          path_helpers = route_pairs.map do |global_route, organization_route|
            generate_path_helper(global_route, organization_route)
          end.join("\n")

          output = <<~JS
            #{GENERATED_FILE_HEADER}
            import { __jsr } from '~/lib/utils/path_helpers/core';
            #{utils_import_statement(path_helpers)}

            #{path_helpers}
          JS
          file_path = Rails.root.join(base_path, "#{namespace}.js")

          write_file_if_changed(file_path, output)
        end
      end

      def generate_path_helper(global_route, organization_route)
        return generate_path_helper_without_organization_scoping(global_route) if organization_route.nil?

        # To support short hand project helpers defined in
        # https://gitlab.com/gitlab-org/gitlab/-/blob/4202e37329fb343ae674db79593ce04427ebab6b/config/routes.rb#L368
        if global_route.name.include?('namespace_project')
          return generate_project_path_helper(global_route, organization_route)
        end

        generate_standard_path_helper(global_route, organization_route)
      end

      # To support short hand project helpers defined in
      # https://gitlab.com/gitlab-org/gitlab/-/blob/4202e37329fb343ae674db79593ce04427ebab6b/config/routes.rb#L368
      def generate_project_path_helper(global_route, organization_route)
        # `config/routes.rb` registers a shorthand `direct` URL helper for every
        # `namespace_project_*` route by substituting the prefix (e.g.
        # `namespace_project_jobs` -> `project_jobs`). The shorthand is what views
        # and Ruby code use, so it's what we document in the JSDoc and use for the JS export.
        shorthand_route_name = global_route.name.sub('namespace_project', 'project')

        global_jsdoc, global_path_helper_name, global_path_helper =
          generate_global_path_helper(global_route, rails_route_name: shorthand_route_name)
        organization_path_helper_name, organization_path_helper = generate_organization_path_helper(
          organization_route
        )

        private_global_path_helper_name = private_path_helper_name(global_path_helper_name)
        private_organization_path_helper_name = private_path_helper_name(organization_path_helper_name)

        # Adjust arguments in JSDoc to show projectPath as the argument
        jsdoc = annotate_jsdoc_with_organization_path_option(
          global_jsdoc
            .sub(%r{\*namespace_id/:(?:project_)?id}, ':project_full_path')
            .sub(
              / \* @param {any} namespaceId\n \* @param {any} (?:project)?[Ii]d/,
              ' * @param {string} projectFullPath'
            )
        )

        project_path_helper_name = "#{shorthand_route_name}_path".camelize(:lower)

        <<~JS
            #{jsdoc}export const #{project_path_helper_name} = /*#__PURE__*/ (projectFullPath, ...args) => {
              const #{private_organization_path_helper_name} = #{organization_path_helper};
              const #{private_global_path_helper_name} = #{global_path_helper};

              const { namespacePath, projectPath } = splitProjectFullPath(projectFullPath);
              const { organizationPath, routeArgs } = resolveOrganizationScope(args);

              if (organizationPath) {
                return #{private_organization_path_helper_name}(organizationPath, namespacePath, projectPath, ...routeArgs);
              }

              return #{private_global_path_helper_name}(namespacePath, projectPath, ...routeArgs);
            };
        JS
      end

      def generate_standard_path_helper(global_route, organization_route)
        global_jsdoc, global_path_helper_name, global_path_helper = generate_global_path_helper(global_route)
        organization_path_helper_name, organization_path_helper = generate_organization_path_helper(
          organization_route
        )

        private_global_path_helper_name = private_path_helper_name(global_path_helper_name)
        private_organization_path_helper_name = private_path_helper_name(organization_path_helper_name)

        <<~JS
          #{annotate_jsdoc_with_organization_path_option(global_jsdoc)}export const #{global_path_helper_name} = /*#__PURE__*/ (...args) => {
            const #{private_organization_path_helper_name} = #{organization_path_helper};
            const #{private_global_path_helper_name} = #{global_path_helper};

            const { organizationPath, routeArgs } = resolveOrganizationScope(args);

            if (organizationPath) {
              return #{private_organization_path_helper_name}(organizationPath, ...routeArgs);
            }

            return #{private_global_path_helper_name}(...routeArgs);
          };
        JS
      end

      def generate_path_helper_without_organization_scoping(global_route)
        jsdoc, path_helper_name, path_helper = generate_global_path_helper(global_route)

        return '' if path_helper_name.nil? || path_helper.nil?

        <<~JS
          #{jsdoc}export const #{path_helper_name} = #{path_helper};
        JS
      end

      # Generate path helper for global route
      def generate_global_path_helper(global_route, rails_route_name: global_route.name)
        jsdoc, name, helper = ::JsRoutes::Route.new(
          ::JsRoutes.configuration,
          global_route
        ).helpers[0]

        [annotate_jsdoc_with_rails_route(jsdoc, global_route, rails_route_name), name, helper]
      end

      # Expand the JSDoc with the Rails route metadata so the generated helper
      # can be found by searching for the Rails route name used in views.
      def annotate_jsdoc_with_rails_route(jsdoc, global_route, rails_route_name)
        jsdoc.sub(/^ \* Generates rails route to\n \* (?<href>.+)\n/) do
          href = Regexp.last_match[:href]
          lines = [
            ' * Generates the Rails route:',
            ' *',
            " * - href: `#{href}`",
            " * - Path helper: `#{rails_route_name}_path`",
            " * - URL helper: `#{rails_route_name}_url`"
          ]

          controller_action = route_controller_action(global_route)
          lines << " * - controller#action: `#{controller_action}`" if controller_action

          lines << ' *'

          "#{lines.join("\n")}\n"
        end
      end

      # Only helpers with an organization scoped counterpart run `resolveOrganizationScope`, so
      # only those document `organizationPath`. Anywhere else it would be serialized into the
      # query string rather than switching the scope.
      def annotate_jsdoc_with_organization_path_option(jsdoc)
        jsdoc.sub(/^ \* @param \{object \| undefined\} options\n/) do |options_param|
          "#{options_param} * @param {string | null | undefined} options.organizationPath Path of organization to " \
            "nest under. Pass `null` to remove path from URL params when outside of an organization data context.\n"
        end
      end

      def route_controller_action(global_route)
        controller = global_route.requirements[:controller]
        action = global_route.requirements[:action]
        return unless controller && action

        "#{controller}##{action}"
      end

      # Generate path helper for scoped organization route
      def generate_organization_path_helper(organization_route)
        _, organization_path_helper_name, organization_path_helper = ::JsRoutes::Route.new(
          ::JsRoutes.configuration,
          organization_route
        ).helpers[0]

        [organization_path_helper_name, organization_path_helper]
      end

      # Prefix path helper name with underscore to mark as private
      def private_path_helper_name(path_helper_name)
        "_#{path_helper_name}"
      end

      def utils_import_statement(path_helpers)
        imports = %w[resolveOrganizationScope splitProjectFullPath].select do |name|
          path_helpers.include?(name)
        end

        return '' if imports.empty?

        <<~JS
          import { #{imports.join(', ')} } from '~/lib/utils/path_helpers/utils';
        JS
      end

      def javascript_utils
        <<~JS
          #{GENERATED_FILE_HEADER}
          // js-routes reads the trailing argument as a route parameter rather than an options
          // hash when it carries `id`, `to_param` or `toParam`. Mirrors `looks_like_serialized_model`
          // in `core.js`, which is where `extract_options` makes the same call.
          const isOptionsObject = (value) =>
            Object.prototype.toString.call(value) === '[object Object]' &&
            ('_options' in value || !('id' in value || 'to_param' in value || 'toParam' in value));

          // Mirror `::Current.data_context` and `::Current.organization_resolver&.from_organization_params&.path` in
          // `Routing::OrganizationsHelper::MappedHelpers#scoped_path_for`.
          const dataContextOrganizationPath = () => gon?.data_context_organization_path;
          const requestOrganizationPath = () => gon?.organization_path;

          // Strip `organizationPath` so js-routes does not turn it into a query parameter.
          const withoutOrganizationPathOption = (args) => {
            const { organizationPath, ...routeOptions } = args.at(-1);

            return [...args.slice(0, -1), routeOptions];
          };

          // Mirrors `Routing::OrganizationsHelper::MappedHelpers#scoped_path_for`.
          export const resolveOrganizationScope = (args) => {
            const options = args.at(-1);
            const hasOrganizationPathOption = isOptionsObject(options) && 'organizationPath' in options;
            const routeArgs = hasOrganizationPathOption ? withoutOrganizationPathOption(args) : args;
            const dataContextPath = dataContextOrganizationPath();

            if (dataContextPath) {
              return { organizationPath: dataContextPath, routeArgs };
            }

            // `null` opts out of organization scoping, `undefined` reads as "not specified"
            // so that an unresolved value does not silently drop the request's own scope.
            if (hasOrganizationPathOption && options.organizationPath !== undefined) {
              return { organizationPath: options.organizationPath, routeArgs };
            }

            return { organizationPath: requestOrganizationPath(), routeArgs };
          };

          // The private `namespaceProject` helpers expect separate `namespacePath`
          // and `projectPath` arguments. Typically we only have `project.fullPath`
          // available on the frontend. This util splits `project.fullPath` into
          // separate arguments so they can be passed to the private `namespaceProject` helpers.
          export const splitProjectFullPath = (projectFullPath) => {
            if (!projectFullPath) {
              throw new Error('Route missing required keys: projectFullPath');
            }

            if (typeof projectFullPath !== 'string') {
              throw new Error('projectFullPath must be a string');
            }

            const splitProjectFullPath = projectFullPath.split("/");
            const namespacePath = splitProjectFullPath.slice(0, -1).join("/");
            const projectPath = splitProjectFullPath.at(-1);

            return { namespacePath, projectPath };
          };
        JS
      end
    end
  end
end
